    (hA : A.IsIrreducible) {p : ι → ℝ} {r : ℝ}
    (hp : ∀ i, 0 ≤ p i) (hpne : p ≠ 0) (heig : A *ᵥ p = r • p) :
    ∀ i, 0 < p i

theorem IsIrreducible.rootMultiplicity_perron_eq_one {A : Matrix ι ι ℝ}
    (hA : A.IsIrreducible) (hAne : A ≠ 0) :
    A.charpoly.rootMultiplicity (spectralRadius ℂ (A.map Complex.ofReal)).toReal = 1

theorem mul_apply_nonneg_of_nonneg {A : Matrix ι κ ℝ} {B : Matrix κ η ℝ}
    (hA : ∀ i j, 0 ≤ A i j) (hB : ∀ i j, 0 ≤ B i j) (i : ι) (j : η) :
    0 ≤ (A * B) i j

theorem IsZMatrix.schurComplement {E : Matrix ι ι ℝ} {F : Matrix ι κ ℝ}
    {G : Matrix κ ι ℝ} {H : Matrix κ κ ℝ}
    (hA : (Matrix.fromBlocks E F G H).IsZMatrix) (hE : E.IsNonsingularMMatrix) :
    (H - G * E⁻¹ * F).IsZMatrix

theorem IsNonsingularMMatrix.nonneg_of_mulVec_nonneg
    {A : Matrix ι ι ℝ} (hA : A.IsNonsingularMMatrix) {u : ι → ℝ}
    (hu : ∀ i, 0 ≤ (A *ᵥ u) i) : ∀ i, 0 ≤ u i

theorem isNonsingularMMatrix_iff_positive_certificate {A : Matrix ι ι ℝ}
    (hA : A.IsZMatrix) : A.IsNonsingularMMatrix ↔
      ∃ x : ι → ℝ, (∀ i, 0 < x i) ∧ ∀ i, 0 < (A *ᵥ x) i

theorem pow_apply_le_of_nonneg_of_le {A B : Matrix ι ι ℝ}
    (hA : ∀ i j, 0 ≤ A i j) (hAB : ∀ i j, A i j ≤ B i j)
    (k : ℕ) (i j : ι) : (A ^ k) i j ≤ (B ^ k) i j

theorem spectralRadius_complexification_mono {A B : Matrix ι ι ℝ}
    (hA : ∀ i j, 0 ≤ A i j) (hAB : ∀ i j, A i j ≤ B i j) :
    spectralRadius ℂ (A.map Complex.ofReal) ≤ spectralRadius ℂ (B.map Complex.ofReal)

theorem IsIrreducible.spectralRadius_add_lt {A E : Matrix ι ι ℝ}
    (hA : A.IsIrreducible) (hAne : A ≠ 0) (hE : ∀ i j, 0 ≤ E i j) (hEne : E ≠ 0) :
    spectralRadius ℂ (A.map Complex.ofReal) < spectralRadius ℂ ((A + E).map Complex.ofReal)

private theorem mulVec_pos_of_pos_of_sum_one {A : Matrix ι ι ℝ}
    (hA : ∀ i j, 0 < A i j) {x : ι → ℝ}
    (hx : ∀ i, 0 ≤ x i) (hs : ∑ i, x i = 1) (i : ι) : 0 < (A *ᵥ x) i

private theorem pos_of_mem_positiveSubsolutionSlice {A : Matrix ι ι ℝ} {R : ℝ}
    (hA : ∀ i j, 0 < A i j) {x : ι → ℝ}
    (hx : x ∈ positiveSubsolutionSlice A R) (i : ι) : 0 < x i

theorem spectralRadius_le_of_abs_le_nonnegative {A : Matrix ι ι ℝ} {B : Matrix ι ι ℂ}
    (hA : ∀ i j, 0 ≤ A i j) (hBA : ∀ i j, norm (B i j) ≤ A i j) :
    spectralRadius ℂ B ≤ spectralRadius ℂ (A.map Complex.ofReal)

theorem peripheral_eigenvector_eq_smul_of_pos {B : Matrix ι ι ℝ}
    (hB : ∀ i j, 0 < B i j) {p : ι → ℝ} {r : ℝ}
    (hp : ∀ i, 0 < p i) (hr : 0 < r) (hBp : B *ᵥ p = r • p)
    {z : ι → ℂ} {μ : ℂ} (hBz : B.map Complex.ofReal *ᵥ z = μ • z) (hμ : ‖μ‖ = r) :
    ∃ c : ℂ, z = c • (fun i => (p i : ℂ))

theorem IsPrimitive.peripheral_eigenvalue_eq_perron {A : Matrix ι ι ℝ}
    (hA : A.IsPrimitive) (hAne : A ≠ 0) {μ : ℂ}
    (hμ : μ ∈ spectrum ℂ (A.map Complex.ofReal))
    (hμnorm : ‖μ‖ = (spectralRadius ℂ (A.map Complex.ofReal)).toReal) :
    μ = ((spectralRadius ℂ (A.map Complex.ofReal)).toReal : ℂ)

theorem IsNonsingularMMatrix.re_pos_of_mem_spectrum {A : Matrix ι ι ℝ}
    (hA : A.IsNonsingularMMatrix) {μ : ℂ} (hμ : μ ∈ spectrum ℂ (A.map Complex.ofReal)) :
    0 < μ.re

theorem isPrimitive_of_tendsto_normalized_pow_pos {A P : Matrix ι ι ℝ} {r : ℝ}
    (hA : ∀ i j, 0 ≤ A i j) (hr : 0 < r) (hP : ∀ i j, 0 < P i j)
    (hlim : Tendsto (fun k : ℕ => (r⁻¹ • A) ^ k) atTop (𝓝 P)) : A.IsPrimitive

theorem mul_eq_of_range_le_of_isIdempotentElem {n r : Type*}
    [Fintype n] [Fintype r] {P : Matrix n n ℝ} {Q : Matrix n r ℝ}
    (hP : IsIdempotentElem P)
