theorem specNorm_add_le_max_of_projector_supports {P : Matrix n n 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) {X Y : Matrix m n 𝕜}
    (hX : X * P = X) (hY : Y * (1 - P) = Y) (hXY : Xᴴ * Y = 0) :
