theorem frobSq_one_sub_mul_eq_re_trace {P : Matrix m m 𝕜}
    (hP : IsStarProjection P) (A : Matrix m n 𝕜) :
    frobSq ((1 - P) * A) = RCLike.re ((1 - P) * (A * Aᴴ)).trace

theorem frobSq_mul_eq_of_mul_conjTranspose_eq {A : Matrix m n 𝕜}
    {B : Matrix m l 𝕜} (h : A * Aᴴ = B * Bᴴ) (C : Matrix m m 𝕜) :
    frobSq (C * A) = frobSq (C * B)

theorem IsSVD.frobSq_projector_tail_le_sum_shifted {p q : ℕ} {A : Matrix m n 𝕜}
    {U : Matrix m (Fin p) 𝕜} {V : Matrix n (Fin q) 𝕜} (h : IsSVD A U V)
    {ℓ k : ℕ} (hℓp : ℓ ≤ p) {P : Matrix m m 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) (hr : P.rank ≤ k) :
    frobSq (P * (A - h.truncatedMatrix ℓ)) ≤
      ∑ j ∈ Finset.range k, singularValues A (ℓ + j) ^ 2

theorem IsSVD.mul_frobSq_projector_tail_le_mul_bestRankFrobSq {p q : ℕ} {A : Matrix m n 𝕜}
    {U : Matrix m (Fin p) 𝕜} {V : Matrix n (Fin q) 𝕜} (h : IsSVD A U V)
    {ℓ k : ℕ} (hℓp : ℓ ≤ p) (hkl : k ≤ ℓ) {P : Matrix m m 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) (hr : P.rank ≤ k) :
    (ℓ : ℝ) * frobSq (P * (A - h.truncatedMatrix ℓ)) ≤
      (k : ℝ) * bestRankFrobSq A k

theorem exists_eq_mul_of_range_le {a b : Type*} [Fintype a] [Fintype b] {X : Matrix n a ℝ}
    {Y : Matrix n b ℝ} (h : LinearMap.range Y.mulVecLin ≤ LinearMap.range X.mulVecLin) :
    ∃ R : Matrix a b ℝ, Y = X * R

theorem overlapTangentNorm_eq_of_range_eq (Q : Matrix n k ℝ) {X Y : Matrix n k ℝ}
    (h : LinearMap.range X.mulVecLin = LinearMap.range Y.mulVecLin) (hX : IsUnit (Qᵀ * X)) :
    overlapTangentNorm Q X = overlapTangentNorm Q Y

theorem directedSubspaceGap_comm {𝕜 : Type*} [RCLike 𝕜] {Q X : Matrix n k 𝕜}
    (hQ : HasOrthonormalCols Q) (hX : HasOrthonormalCols X) :
    directedSubspaceGap Q X = directedSubspaceGap X Q

theorem frobSq_residual_eq_card_sub {Q : Matrix n k ℝ} {Q' : Matrix n k' ℝ}
    (hQ : HasOrthonormalCols Q) (hQ' : HasOrthonormalCols Q') :
    frobSq (projResidual Q Q') = Fintype.card k' - frobSq (Qᵀ * Q')

theorem frobNorm_mul_frame_le_sqrt_card_mul_specNorm {Q : Matrix n r ℝ}
    (hQ : HasOrthonormalCols Q) (E : Matrix m n ℝ) :
    frobNorm (E*Q) ≤ Real.sqrt (Fintype.card r)*specNorm E

theorem IsSVD.inv_eq {k : ℕ} {C U V : Matrix (Fin k) (Fin k) ℝ}
    (h : IsSVD C U V) (hC : IsUnit C) :
    C⁻¹=V*Matrix.diagonal (fun i : Fin k => (singularValues C i)⁻¹)*Uᵀ

theorem IsSVD.one_sub_transpose_mul_self {k : ℕ} {C U V : Matrix (Fin k) (Fin k) ℝ}
    (h : IsSVD C U V) :
    1-Cᵀ*C=V*Matrix.diagonal (fun i : Fin k => 1-singularValues C i^2)*Vᵀ

theorem frobSq_mul_projector_eq_re_trace_mul {P : Matrix n n 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) (A : Matrix m n 𝕜) :
    frobSq (A * P) = RCLike.re (P * (Aᴴ * A)).trace

theorem one_sub_projector_isHermitian_isIdempotentElem {P : Matrix n n 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) :
    (1 - P).IsHermitian ∧ IsIdempotentElem (1 - P)

theorem frobSq_projector_mul_add_complement {Q : Matrix m m 𝕜}
    (hs : Q.IsHermitian) (hp : IsIdempotentElem Q) (Z : Matrix m n 𝕜) :
    frobSq (Q * Z) + frobSq ((1 - Q) * Z) = frobSq Z

theorem frobSq_mul_projector_add_complement {P : Matrix n n 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) (Z : Matrix m n 𝕜) :
    frobSq (Z * P) + frobSq (Z * (1 - P)) = frobSq Z

theorem frobSq_one_sub_projector_mul_le {P : Matrix m m 𝕜}
    (hs : P.IsHermitian) (hp : IsIdempotentElem P) (A : Matrix m n 𝕜) :
    frobSq ((1 - P) * A) ≤ frobSq A

theorem residual_mul_eq_zero_of_range {Q : Matrix m q 𝕜} {A : Matrix m n 𝕜} {p : Type*}
    [Fintype p] {Ω : Matrix n p 𝕜} (h : Q * (Qᴴ * (A * Ω)) = A * Ω) :
    projResidual Q A * Ω = 0

theorem frobSq_eq_frobSq_proj_add_residual [DecidableEq q] {Q : Matrix m q 𝕜}
    (hQ : HasOrthonormalCols Q) (A : Matrix m n 𝕜) :
    frobSq A = frobSq (Q * (Qᴴ * A)) + frobSq (projResidual Q A)

theorem frobSq_eq_frobSq_conjTranspose_mul_add_residual [DecidableEq q] {Q : Matrix m q 𝕜}
    (hQ : HasOrthonormalCols Q) (A : Matrix m n 𝕜) :
    frobSq A = frobSq (Qᴴ * A) + frobSq (projResidual Q A)

theorem frobSq_residual_le_frobSq_sub_mul [DecidableEq q] {Q : Matrix m q 𝕜}
    (hQ : HasOrthonormalCols Q) (A : Matrix m n 𝕜) (B : Matrix q n 𝕜) :
    frobSq (projResidual Q A) ≤ frobSq (A - Q * B)

theorem frobSq_sub_mul_le_of_isBestFrobRankApprox [DecidableEq q] {k : ℕ} {Q : Matrix m q 𝕜}
    (hQ : HasOrthonormalCols Q) {A : Matrix m n 𝕜} {Y : Matrix q n 𝕜}
    (hY : IsBestFrobRankApprox (Qᴴ * A) k Y) (B : Matrix q n 𝕜) (hB : B.rank ≤ k) :
    frobSq (A - Q * Y) ≤ frobSq (A - Q * B)

theorem mulVec_conjTranspose_mulVec_of_mem_range [Fintype m] [DecidableEq q]
    {Q : Matrix m q 𝕜} (hQ : HasOrthonormalCols Q) {x : m → 𝕜}
    (hx : x ∈ LinearMap.range Q.mulVecLin) : Q *ᵥ (Qᴴ *ᵥ x) = x

theorem sum_norm_sq_conjTranspose_mulVec_le [DecidableEq q] {Q : Matrix m q 𝕜}
    (hQ : HasOrthonormalCols Q) (x : m → 𝕜) :
    ∑ i, ‖(Qᴴ *ᵥ x) i‖ ^ 2 ≤ ∑ i, ‖x i‖ ^ 2

theorem mul_conjTranspose_mul_eq_of_range_le [Fintype m] [DecidableEq q] {q' : Type*}
    [Fintype q'] {Q : Matrix m q' 𝕜} {Q' : Matrix m q 𝕜} (hQ' : HasOrthonormalCols Q')
    (h : LinearMap.range Q.mulVecLin ≤ LinearMap.range Q'.mulVecLin) : Q' * (Q'ᴴ * Q) = Q

theorem exists_sign_frobNorm_sub_le_projector {U W : Matrix m (Fin 1) ℝ}
    (hU : HasOrthonormalCols U) (hW : HasOrthonormalCols W) :
    ∃ s : ℝ, s ^ 2 = 1 ∧ frobNorm (W - s • U) ≤ frobNorm (U * Uᵀ - W * Wᵀ)

theorem HasOrthonormalCols.mul {m n p : Type*} [Fintype m] [Fintype n]
    [DecidableEq n] [DecidableEq p] {P : Matrix m n 𝕜} {Q : Matrix n p 𝕜}
    (hP : HasOrthonormalCols P) (hQ : HasOrthonormalCols Q) : HasOrthonormalCols (P * Q)

theorem HasOrthonormalCols.isIdempotentElem_mul_conjTranspose {m n : Type*}
    [Fintype m] [Fintype n] [DecidableEq n] {Q : Matrix m n 𝕜}
    (hQ : HasOrthonormalCols Q) : IsIdempotentElem (Q * Qᴴ)

theorem HasOrthonormalCols.submatrix_cols {m n r : Type*} [Fintype m] [Fintype n]
    [Fintype r] [DecidableEq n] [DecidableEq r] {Q : Matrix m n 𝕜}
    (hQ : HasOrthonormalCols Q) (e : r ↪ n) : HasOrthonormalCols (Q.submatrix id e)

private theorem orthogonal_blockDiagonal {p q : Type*}
    [Fintype p] [Fintype q] [DecidableEq p] [DecidableEq q]
    {A : Matrix p p ℝ} {B : Matrix q q ℝ}
    (hA : HasOrthonormalCols A) (hB : HasOrthonormalCols B) :
