theorem unitaryQRNormalizedArray_unitary_mul {n k : ℕ}
    (O : Matrix.unitaryGroup (Fin n) 𝕜) (A : Matrix (Fin n) (Fin k) 𝕜) :
    unitaryQRNormalizedArray 𝕜 (O.val*A) = O.val*unitaryQRNormalizedArray 𝕜 A

private theorem native_singularValue_zero_eq_specNorm {m n : Type*}
    [Fintype m] [Fintype n] [DecidableEq m] [DecidableEq n] (A : Matrix m n ℝ) :
    singularValues A 0 = specNorm A

theorem sin_principalAngles_monotone {P Q : Matrix m n ℝ}
    (hP : HasOrthonormalCols P) (hQ : HasOrthonormalCols Q) :
    Monotone (fun i => Real.sin (principalAnglesFintype P Q i))

theorem vectorTangentToFrame_eq_zero_of_projection_eq_zero
    {l : Type*} [Fintype l] (Q : Matrix n l ℝ) {u : n → ℝ}
    (hp : Qᵀ *ᵥ u = 0) : vectorTangentToFrame Q u = 0

theorem hasOrthonormalCols_tailColumns {m : Type*} [Fintype m] {n k : ℕ}
    {Q : Matrix m (Fin n) ℝ} (hQ : HasOrthonormalCols Q) (hk : k ≤ n) :
    HasOrthonormalCols (tailColumns Q hk)

theorem mul_headColumns {m r : Type*} [Fintype r] {n k : ℕ}
    (A : Matrix m r ℝ) (Q : Matrix r (Fin n) ℝ) (hk : k ≤ n) :
    A * headColumns Q hk = headColumns (A * Q) hk

theorem mul_tailColumns {m r : Type*} [Fintype r] {n k : ℕ}
    (A : Matrix m r ℝ) (Q : Matrix r (Fin n) ℝ) (hk : k ≤ n) :
    A * tailColumns Q hk = tailColumns (A * Q) hk

theorem specNorm_tangentPrincipalAngles_eq_residual_mul_inv {P Q : Matrix m n ℝ}
    (hP : HasOrthonormalCols P) (hQ : HasOrthonormalCols Q) (hC : IsUnit (Pᵀ*Q)) :
    specNorm (tangentPrincipalAngles P Q)=specNorm (projResidual P Q*(Pᵀ*Q)⁻¹)

theorem specNorm_tangentPrincipalAngles_eq_complement_overlap_mul_inv {r : Type*}
    [Fintype r] [DecidableEq r] {P Q : Matrix m n ℝ} {R : Matrix m r ℝ}
    (hP : HasOrthonormalCols P) (hQ : HasOrthonormalCols Q) (hR : HasOrthonormalCols R)
    (hcomp : P*Pᵀ+R*Rᵀ=1) (hC : IsUnit (Pᵀ*Q)) :
    specNorm (tangentPrincipalAngles P Q)=specNorm ((Rᵀ*Q)*(Pᵀ*Q)⁻¹)

theorem rangeProjector_mul_of_range_le {B : Matrix m n 𝕜} {Y : Matrix m k 𝕜}
    (h : LinearMap.range Y.mulVecLin ≤ LinearMap.range B.mulVecLin) :
    rangeProjector B * Y = Y

theorem rangeProjector_mul_rangeProjector_of_mul_eq {Q : Matrix m k 𝕜} {Y : Matrix m l 𝕜}
    (h : rangeProjector Q * Y = Y) :
    rangeProjector Q * rangeProjector Y = rangeProjector Y

theorem rangeProjector_eq_of_range_eq {A : Matrix m n 𝕜} {B : Matrix m k 𝕜}
    (h : LinearMap.range A.mulVecLin = LinearMap.range B.mulVecLin) :
