theorem IsSVD.frobSq_eq_sum_left_singularValues_sq {p q : ℕ} {Y : Matrix m n 𝕜}
    {U : Matrix m (Fin p) 𝕜} {V : Matrix n (Fin q) 𝕜} (h : IsSVD Y U V) :
    frobSq Y = ∑ i : Fin p, singularValues Y i ^ 2

theorem re_quadForm_le_of_add_conjTranspose_le {A : Matrix n n 𝕜} {a : ℝ}
    (hA : A + Aᴴ ≤ (-2 * a) • (1 : Matrix n n 𝕜)) (v : n → 𝕜) :
