theorem quadForm_richardsonIterate_sub_le {A : Matrix n n ℝ} (hA : A.IsHermitian) {a b ω : ℝ}
    (hω : 0 ≤ ω) (hspec : ∀ i, hA.eigenvalues i ∈ Set.Icc a b) {g : ℝ[X]}
