        (singularValues (A + E) (k - 1) - singularValues A k)

theorem sqrt_add_sq_frobNorm_sinePrincipalAngles_le_sqrt_add_sq_residual_div
    {m n k : ℕ} {A E : Matrix (Fin m) (Fin n) ℝ}
    {U Uhat : Matrix (Fin m) (Fin m) ℝ} {V Vhat : Matrix (Fin n) (Fin n) ℝ}
    (hA : IsSVD A U V) (hhat : IsSVD (A + E) Uhat Vhat) (hk : k ≤ min m n)
    (hδ : 0 < singularValues (A + E) (k - 1) - singularValues A k) :
    let U₁
:= headColumns U (hk.trans (min_le_left m n))
    let V₁ := headColumns V (hk.trans (min_le_right m n))
    let Uhat₁ := headColumns Uhat (hk.trans (min_le_left m n))
    let Vhat₁ := headColumns Vhat (hk.trans (min_le_right m n))
    let T := Matrix.diagonal (fun i : Fin k => singularValues (A + E) i)
    Real.sqrt (frobNorm (sinePrincipalAngles U₁ Uhat₁) ^ 2 +
      frobNorm (sinePrincipalAngles V₁ Vhat₁) ^ 2) ≤
      Real.sqrt (frobNorm (A * Vhat₁ - Uhat₁ * T) ^ 2 +
        frobNorm (Aᵀ * Uhat₁ - Vhat₁ * T) ^ 2) /
          (singularValues (A + E) (k - 1) - singularValues A k)

theorem finLobattoSchurBorder_bounds_and_endpoints {q : ℕ}
    {J : Matrix (Fin q) (Fin q) ℝ} {e : Fin q → ℝ} {a c : ℝ}
    (hac : a < c) (hJa : (J - a • 1).PosDef) (hJc : (c • 1 - J).PosDef) (he : e ≠ 0) :
    let B
:= finSymmetricBorder J (Real.sqrt (lobattoCouplingSq J e a c) • e) (lobattoCorner J e a c)
    a • 1 ≤ B ∧ B ≤ c • 1 ∧ a ∈ spectrum ℝ B ∧ c ∈ spectrum ℝ B

theorem matrixSign_spectral_projectors {A : Matrix n n ℂ}
    (hA : ∀ z ∈ spectrum ℂ A, z.re ≠ 0) :
    let S
:= matrixSign A
    let P := (2 : ℂ)⁻¹ • (1+S)
    let Q := (2 : ℂ)⁻¹ • (1-S)
    IsMatrixSign A S ∧ P*P=P ∧ Q*Q=Q ∧ P*Q=0 ∧ Q*P=0 ∧ P+Q=1 ∧
      LinearMap.range P.toLin' = matrixSpectralSubspace A {z | 0 < z.re} ∧
      LinearMap.range Q.toLin' = matrixSpectralSubspace A {z | z.re < 0}

theorem projectedLyapunov_residual_norms_and_rank {A : Matrix n n 𝕜}
    {V : Matrix n k 𝕜} {U : Matrix n l 𝕜} {H Y : Matrix k k 𝕜}
    {T : Matrix l k 𝕜} {B : Matrix n s 𝕜} {Bk : Matrix k s 𝕜}
    (hV : HasOrthonormalCols V) (hU : HasOrthonormalCols U) (hVU : Vᴴ * U = 0)
    (hAV : A * V = V * H + U * T) (hB : B = V * Bk)
    (hYH : Y.IsHermitian) (hY : H * Y + Y * Hᴴ + Bk * Bkᴴ = 0) :
    let R
:= A * (V * Y * Vᴴ) + (V * Y * Vᴴ) * Aᴴ + B * Bᴴ
    frobNorm R = Real.sqrt 2 * frobNorm (T * Y) ∧
      specNorm R = specNorm (T * Y) ∧ R.rank = 2 * (T * Y).rank
